public static String computeWithBuiltIn(String s) {
    String[] words = s.trim().split("\\s+");
    StringBuilder sb = new StringBuilder();

    for (int i = words.length - 1; i >= 0; i--) {
        sb.append(words[i]);
        if (i > 0) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

public static String computeWithStringBuilder(String s) {
    StringBuilder sb = new StringBuilder();
    List<String> words = new ArrayList<>();
    StringBuilder currentWord = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            if (currentWord.length() > 0) {
                words.add(currentWord.toString());
                currentWord.setLength(0);
            }
        } else {
            currentWord.append(c);
        }
    }
    if (currentWord.length() > 0) {
        words.add(currentWord.toString());
    }

    for (int i = words.size() - 1; i >= 0; i--) {
        sb.append(words.get(i));
        if (i > 0) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

public static String computeWithTwoPass(String s) {
    s = s.trim();
    StringBuilder sb = new StringBuilder();
    int end = s.length();

    for (int i = s.length() - 1; i >= 0; i--) {
        if (s.charAt(i) == ' ') {
            if (i < end - 1) {
                if (sb.length() > 0) {
                    sb.append(" ");
                }
                sb.append(s.substring(i + 1, end));
            }
            end = i;
        }
    }

    if (end > 0) {
        if (sb.length() > 0) {
            sb.append(" ");
        }
        sb.append(s.substring(0, end));
    }
    return sb.toString();
}
